function validate([a, b]) {
  if (typeof a !== 'string' || typeof b !== 'string') return 'a and b must be strings.';
  if (a.length < 1 || a.length > 100000) return 'a needs 1 to 100000 letters.';
  if (a.length !== b.length) return 'a and b must have the same length.';
  if (!/^[a-z]*$/.test(a) || !/^[a-z]*$/.test(b)) return 'Use lowercase English letters only.';
  return null;
}

