function checkPalindromeFormation(a, b) {
  const isPalindrome = (s, left, right) => {
    while (left < right) {
      if (s[left] !== s[right]) {
        return false;
      }
      left++;
      right--;
    }
    return true;
  };

  const canJoin = (front, back) => {
    let left = 0;
    let right = front.length - 1;
    while (left < right && front[left] === back[right]) {
      left++;
      right--;
    }
    return isPalindrome(front, left, right) || isPalindrome(back, left, right);
  };

  return canJoin(a, b) || canJoin(b, a);
}

