function checkPalindromeFormation(a, b) {
  const palindrome = s => s === s.split('').reverse().join('');
  for (let cut = 0; cut <= a.length; cut++) {
    if (palindrome(a.slice(0, cut) + b.slice(cut))) return true;
    if (palindrome(b.slice(0, cut) + a.slice(cut))) return true;
  }
  return false;
}

