function generate(rand, size) {
  const letters = size === 'large' ? 'abc' : 'ab'.slice(0, 1 + Math.floor(rand() * 2)) + (rand() < 0.5 ? 'c' : '');
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const word = len => Array.from({ length: len }, pick).join('');
  const n = size === 'large' ? 3000 + Math.floor(rand() * 2000) : 1 + Math.floor(rand() * 8);
  const mode = rand();
  if (mode < 0.25) return [word(n), word(n)];
  // Build a palindrome and hide its outer parts in the two strings, with a middle that may or may not fit.
  const half = Array.from({ length: Math.ceil(n / 2) }, pick);
  const pal = [...half, ...half.slice(0, Math.floor(n / 2)).reverse()].join('');
  const outer = Math.floor(rand() * (Math.floor(n / 2) + 1));
  let front = pal.slice(0, outer) + word(n - outer);
  let back = word(n - outer) + pal.slice(n - outer);
  if (mode < 0.75) {
    // Copy the palindrome's middle into one of the two strings, so a cut exists.
    const middle = pal.slice(outer, n - outer);
    if (rand() < 0.5) front = pal.slice(0, n - outer) + front.slice(n - outer);
    else back = back.slice(0, outer) + middle + back.slice(n - outer);
  }
  return rand() < 0.5 ? [front, back] : [back, front];
}
